// Looping PCM sample source for the audio probe.
//
// One 16-bit signed sample per tick from a block RAM preloaded at
// synthesis from audio_sample.hex (root-level, generated by
// hw/tools/wav2sample.py — never committed). The address wraps on its
// own because the depth is a power of two; the generator fades the
// ends into each other so the wrap is not a click.
//
// Listening material, because the choice between ladder configurations
// is not settled by distortion figures alone.

module audio_sample_rom #(
    parameter int SAMPLES = 1 << 17   // must be a power of two
) (
    input  logic               i_clk,
    input  logic               i_rst,
    input  logic               i_sample_en,
    output logic signed [15:0] o_sample
);

    localparam int ADDR_W = $clog2(SAMPLES);

    logic [15:0] rom [0:SAMPLES-1];
    initial $readmemh("audio_sample.hex", rom);

    logic [ADDR_W-1:0] addr_q;

    always_ff @(posedge i_clk) begin
        if (i_rst)            addr_q <= '0;
        else if (i_sample_en) addr_q <= addr_q + 1'b1;
    end

    // Registered read: the array maps onto block RAM only if the output
    // is a register.
    always_ff @(posedge i_clk) begin
        if (i_rst)            o_sample <= '0;
        else if (i_sample_en) o_sample <= signed'(rom[addr_q]);
    end

endmodule
